slides.codeSnippet:
read -p "Enter y/n: " choice
case $choice in
  y|Y) echo "You said yes" ;;
  n|N) echo "You said no" ;;
  *) echo "Invalid" ;;
esac

read -p "Filename: " file
case $file in
  *.txt) echo "Text file" ;;
  *.jpg|*.png) echo "Image file" ;;
  *.sh) echo "Shell script" ;;
  *) echo "Unknown type" ;;
esac

echo "1. Show date"
echo "2. List files"
echo "3. Exit"
read -p "Choice: " opt
case $opt in
  1) date ;;
  2) ls ;;
  3) exit ;;
  *) echo "Wrong option" ;;
esac
